// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetIamCapabilityManifest Get the current capability manifest
	// (GET /iam/administration/manifest)
	GetIamCapabilityManifest(ctx context.Context, request GetIamCapabilityManifestRequestObject) (GetIamCapabilityManifestResponseObject, error)
	// ListIamMenus List menus
	// (GET /iam/administration/menus)
	ListIamMenus(ctx context.Context, request ListIamMenusRequestObject) (ListIamMenusResponseObject, error)
	// CreateIamMenu Create a menu
	// (POST /iam/administration/menus)
	CreateIamMenu(ctx context.Context, request CreateIamMenuRequestObject) (CreateIamMenuResponseObject, error)
	// DeleteIamMenu Delete a menu
	// (DELETE /iam/administration/menus/{menuId})
	DeleteIamMenu(ctx context.Context, request DeleteIamMenuRequestObject) (DeleteIamMenuResponseObject, error)
	// UpdateIamMenu Update a menu
	// (PATCH /iam/administration/menus/{menuId})
	UpdateIamMenu(ctx context.Context, request UpdateIamMenuRequestObject) (UpdateIamMenuResponseObject, error)
	// ListIamPermissions List stable Permission Codes
	// (GET /iam/administration/permissions)
	ListIamPermissions(ctx context.Context, request ListIamPermissionsRequestObject) (ListIamPermissionsResponseObject, error)
	// ListIamRoles List roles
	// (GET /iam/administration/roles)
	ListIamRoles(ctx context.Context, request ListIamRolesRequestObject) (ListIamRolesResponseObject, error)
	// CreateIamRole Create a role
	// (POST /iam/administration/roles)
	CreateIamRole(ctx context.Context, request CreateIamRoleRequestObject) (CreateIamRoleResponseObject, error)
	// DeleteIamRole Delete a role
	// (DELETE /iam/administration/roles/{roleId})
	DeleteIamRole(ctx context.Context, request DeleteIamRoleRequestObject) (DeleteIamRoleResponseObject, error)
	// UpdateIamRole Update a role
	// (PATCH /iam/administration/roles/{roleId})
	UpdateIamRole(ctx context.Context, request UpdateIamRoleRequestObject) (UpdateIamRoleResponseObject, error)
	// SetIamRoleGrants Replace role Permission Code and menu grants
	// (PUT /iam/administration/roles/{roleId}/grants)
	SetIamRoleGrants(ctx context.Context, request SetIamRoleGrantsRequestObject) (SetIamRoleGrantsResponseObject, error)
	// ListIamUsers List users within the caller data scope
	// (GET /iam/administration/users)
	ListIamUsers(ctx context.Context, request ListIamUsersRequestObject) (ListIamUsersResponseObject, error)
	// CreateIamUser Create a user
	// (POST /iam/administration/users)
	CreateIamUser(ctx context.Context, request CreateIamUserRequestObject) (CreateIamUserResponseObject, error)
	// GetIamUser Get a user within the caller data scope
	// (GET /iam/administration/users/{userId})
	GetIamUser(ctx context.Context, request GetIamUserRequestObject) (GetIamUserResponseObject, error)
	// UpdateIamUser Update a user
	// (PATCH /iam/administration/users/{userId})
	UpdateIamUser(ctx context.Context, request UpdateIamUserRequestObject) (UpdateIamUserResponseObject, error)
	// GetIamUserDeletion Read the current account deletion lifecycle
	// (GET /iam/administration/users/{userId}/deletion)
	GetIamUserDeletion(ctx context.Context, request GetIamUserDeletionRequestObject) (GetIamUserDeletionResponseObject, error)
	// StartIamUserDeletion Start the single-account deletion lifecycle
	// (POST /iam/administration/users/{userId}/deletion)
	StartIamUserDeletion(ctx context.Context, request StartIamUserDeletionRequestObject) (StartIamUserDeletionResponseObject, error)
	// CancelIamUserDeletion Cancel an account deletion before worker claim
	// (POST /iam/administration/users/{userId}/deletion/cancel)
	CancelIamUserDeletion(ctx context.Context, request CancelIamUserDeletionRequestObject) (CancelIamUserDeletionResponseObject, error)
	// ResetIamUserPassword Reset a user password and revoke sessions
	// (PUT /iam/administration/users/{userId}/password)
	ResetIamUserPassword(ctx context.Context, request ResetIamUserPasswordRequestObject) (ResetIamUserPasswordResponseObject, error)
	// SetIamUserRoles Replace user role assignments
	// (PUT /iam/administration/users/{userId}/roles)
	SetIamUserRoles(ctx context.Context, request SetIamUserRolesRequestObject) (SetIamUserRolesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

